import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { normalizeContext } from '@earendil-works/pi-ai';
import { nativeSubscriptionProvider } from './eval/pi/auth.ts';
import { SubscriptionAuthObservation } from './eval/pi/auth-observation.ts';
import { piQualityProtocol as spec, hash, tokenPolicy } from './eval/pi/protocol.ts';
import { TokenBudget } from './eval/pi/budget.ts';
import { meterProvider } from './eval/provider.ts';
import { evaluationRuntime, outsideCheckout } from './eval/environment.ts';
import { acquireWriterLock } from './src/writer-lock.ts';

const runtime = evaluationRuntime(true, spec.piVersion);
const directory = outsideCheckout(process.env.OPTCHAT_AUTH_OUTPUT);
const previous = await readFile(process.env.OPTCHAT_AUTH_CHECK, 'utf8');
const check = JSON.parse(previous);
if (!check.refreshedLoginReused || check.revision !== runtime.revision)
  throw new Error('Expected the observed native login renewal from this source revision');
await mkdir(directory, { mode: 0o700 });
const unlock = acquireWriterLock(directory);
const specification = {
  id: 'native-pi-post-refresh-smoke/v1',
  model: spec.model,
  thinking: spec.thinking,
  prompt: 'Reply with exactly this text and nothing else: PI_LOGIN_OK',
  callLimit: 1,
  tokenReservation: tokenPolicy.reservationTokens,
  timeoutMs: 60000,
  qualification: 'one authentication smoke request; not a quality or cache study',
};
const budget = new TokenBudget(join(directory, 'tokens.jsonl'), tokenPolicy.reservationTokens, 1, hash(specification));
const observation = new SubscriptionAuthObservation();
const startedAt = new Date().toISOString();
try {
  const base = await nativeSubscriptionProvider(process.env.OPTCHAT_PI_PROFILE, directory, spec, observation);
  const meter = meterProvider(base, 'post-refresh-smoke', join(directory, 'calls.jsonl'), budget, {...spec, maxCallsPerTrial: 1});
  const response = await meter.provider.streamSimple(base.getModels()[0], normalizeContext({
    messages: [{role: 'user', content: specification.prompt, timestamp: Date.now()}],
  })).result();
  const answer = response.content.filter(part => part.type === 'text').map(part => part.text).join('').trim();
  const passed = response.stopReason === 'stop' && answer === 'PI_LOGIN_OK' && !meter.blocked && budget.pendingCalls === 0;
  const result = {
    schema: 'optchat-pi-post-refresh-smoke/v1', ...runtime, startedAt, completedAt: new Date().toISOString(),
    specification, specificationHash: hash(specification),
    authCheckSha256: createHash('sha256').update(previous).digest('hex'),
    passed, exactReply: answer === 'PI_LOGIN_OK', stop: response.stopReason,
    calls: meter.calls.length, tokens: budget.committedTokens, pendingReservations: budget.pendingCalls,
    authObservation: observation.snapshot(), actualSubscriptionChargeUsd: null, remainingSubscriptionQuota: null,
  };
  await writeFile(join(directory, 'report.json'), JSON.stringify(result, null, 2) + '\n', {flag: 'wx', mode: 0o600});
  console.log(JSON.stringify({passed, calls: result.calls, tokens: result.tokens, exactReply: result.exactReply, authObservation: result.authObservation}));
  if (!passed) process.exitCode = 1;
} catch {
  await writeFile(join(directory, 'failure.json'), JSON.stringify({failure: 'post-refresh-smoke-failed', pendingReservations: budget.pendingCalls}) + '\n', {flag: 'wx', mode: 0o600});
  console.error('Post-refresh smoke failed; no retry or API-key fallback.');
  process.exitCode = 1;
} finally { unlock(); }
